def merge_intervals(intervals):
    if not intervals:
        return []
    sorted_intervals = sorted(intervals, key=lambda iv: (iv[0], iv[1]))
    merged = [list(sorted_intervals[0])]
    for start, end in sorted_intervals[1:]:
        last = merged[-1]
        if start <= last[1] + 1:
            last[1] = max(last[1], end)
        else:
            merged.append([start, end])
    return merged

import heapq


def toposort(nodes, edges):
    adj = {n: [] for n in nodes}
    in_degree = {n: 0 for n in nodes}
    seen_edges = set()
    for src, dst in edges:
        key = (src, dst)
        if key in seen_edges:
            continue
        seen_edges.add(key)
        adj[src].append(dst)
        in_degree[dst] += 1

    heap = [n for n in nodes if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for nxt in adj[node]:
            in_degree[nxt] -= 1
            if in_degree[nxt] == 0:
                heapq.heappush(heap, nxt)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return result

def stable_batches(items, limit):
    if limit <= 0:
        raise ValueError("limit πρέπει να είναι θετικός")
    for _name, weight in items:
        if weight <= 0 or weight > limit:
            raise ValueError("κάθε βάρος πρέπει να είναι θετικό και ≤ limit")
    batches = []
    current = []
    current_weight = 0
    for name, weight in items:
        if current and current_weight + weight > limit:
            batches.append(current)
            current = []
            current_weight = 0
        current.append(name)
        current_weight += weight
    if current:
        batches.append(current)
    return batches

import re


def parse_env(text):
    key_re = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')
    result = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' not in line:
            raise ValueError(f"Invalid assignment line: {line!r}")
        key, value = line.split('=', 1)
        key = key.strip()
        if not key_re.fullmatch(key):
            raise ValueError(f"Invalid key: {key!r}")
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ('"', "'"):
            value = value[1:-1]
        result[key] = value
    return result

def parse_sse(chunks):
    data = b''.join(chunks).decode('utf-8')

    events = []
    data_buffer = []

    lines = data.split('\n')
    # A trailing newline (LF or CRLF) produces a spurious empty final segment
    # that is NOT a real blank line; drop it so an unterminated final event
    # is correctly ignored.
    if lines and lines[-1] == '':
        lines = lines[:-1]

    for line in lines:
        if line.endswith('\r'):
            line = line[:-1]  # normalize CRLF

        if line == '':
            # Blank line dispatches the accumulated event.
            if data_buffer:
                event_data = '\n'.join(data_buffer)
                data_buffer = []
                if event_data == '[DONE]':
                    return events
                events.append(event_data)
        elif line.startswith(':'):
            pass  # comment
        else:
            if ':' in line:
                field, _, value = line.partition(':')
            else:
                field, value = line, ''

            if field == 'data':
                if value.startswith(' '):
                    value = value[1:]  # remove at most one space after colon
                data_buffer.append(value)

    return events

import math


def retry_delay(attempt, base, cap):
    if not isinstance(attempt, int) or isinstance(attempt, bool):
        raise ValueError("attempt must be an integer")
    if not isinstance(base, (int, float)) or isinstance(base, bool):
        raise ValueError("base must be a finite number")
    if not isinstance(cap, (int, float)) or isinstance(cap, bool):
        raise ValueError("cap must be a finite number")
    if math.isfinite(base) and math.isfinite(cap):
        pass
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if base < 0 or cap < 0:
        raise ValueError("base and cap must be nonnegative")

    if base == 0:
        # base * 2**attempt is 0 regardless of attempt (cap >= 0).
        return 0.0

    # base > 0: value = base * 2**attempt = ldexp(base, attempt).
    # math.ldexp adjusts the float exponent in O(1) and returns inf on
    # overflow, so attempt = 10**9 never builds a huge integer.
    value = math.ldexp(float(base), attempt)
    if not math.isfinite(value):
        # Overflow -> value is +inf, so min(cap, value) == cap.
        return float(cap)

    return float(min(cap, value))

def fifo_admit(active, queued, budget, slots):
    for reservation in queued:
        if reservation > budget:
            raise ValueError("queued reservation exceeds budget")

    used_slots = len(active)
    used_tokens = sum(active)

    admitted = []
    remaining = []

    for index, reservation in enumerate(queued):
        if used_slots + 1 <= slots and used_tokens + reservation <= budget:
            used_slots += 1
            used_tokens += reservation
            admitted.append(reservation)
        else:
            remaining = list(queued[index:])
            break
    else:
        remaining = []

    return admitted, remaining
